 1	import { createServer } from 'node:http'
 2	
 3	export async function listen(port) {
 4	  const server = createServer((request, response) => {
 5	    if (request.url === '/health') {
 6	      response.writeHead(200, { 'content-type': 'text/plain' })
 7	      response.end('ok')
 8	      return
 9	    }
10	    response.writeHead(404)
11	    response.end()
12	  })
13	  await new Promise((resolve, reject) => {
14	    server.once('error', reject)
15	    server.listen(port, '127.0.0.1', resolve)
16	  })
17	  return {
18	    port: server.address().port,
19	    close: () => new Promise((resolve, reject) => server.close((error) => (error ? reject(error) : resolve()))),
20	  }
21	}
